  getLodOverrideIndexAttr(): Attribute {
    return this.prim.getAttr(UsdLodTokens.lodOverrideIndex)!
  }
  createLodOverrideIndexAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdLodTokens.lodOverrideIndex, "float", false, "varying", defaultValue, writeSparsely)
  }

